<script setup lang="ts">const emit=defineEmits<{submit:[value:{key:string;environment:string;value:Record<string,unknown>;reason:string}]}>();const key=ref("search.result-limit"),environment=ref("production"),value=ref("{\n  \"limit\": 30\n}"),reason=ref("");function submit(){let parsed:Record<string,unknown>;try{parsed=JSON.parse(value.value);}catch{return;}emit("submit",{key:key.value,environment:environment.value,value:parsed,reason:reason.value});}</script><template><section class="admin-panel"><header><div><h2>پیکربندی نسخه‌دار</h2><p>هیچ تغییر تولیدی بدون پیشنهاد و تأیید نفر دوم منتشر نمی‌شود.</p></div><span class="status-pill">چهارچشمی</span></header><form class="admin-config-form" @submit.prevent="submit"><label>کلید تنظیم<input v-model="key" required pattern="[a-z][a-z0-9_.-]{2,79}"></label><label>محیط<select v-model="environment"><option value="staging">آزمایشی</option><option value="production">تولید</option></select></label><label class="wide">مقدار JSON<textarea v-model="value" rows="5" required/></label><label class="wide">علت تغییر<input v-model="reason" required minlength="10" placeholder="اثر و دلیل این تغییر را بنویسید"></label><button class="button button-primary" type="submit">ثبت پیشنهاد تغییر</button></form></section></template>
